import { scheduleCore } from '../../../../utils/schedules/core'

export default defineEventHandler(async (event) => {
  const core = await scheduleCore()
  const id = getRouterParam(event, 'id')!
  const runId = getRouterParam(event, 'runId')!
  // Run ids are generated by us: refuse anything that could escape the runs folder
  if (!/^[\w-]+$/.test(runId)) throw createError({ statusCode: 400, message: 'Invalid run id' })
  const run = core.readRun(id, runId)
  if (!run) throw createError({ statusCode: 404, message: 'Run not found' })
  return { run }
})
